CREATE TABLE Roles(Id int PRIMARY KEY, Name nvarchar(20) NOT NULL UNIQUE);
INSERT Roles VALUES(1,N'Admin'),(2,N'Petugas');
CREATE TABLE Users(Id bigint IDENTITY PRIMARY KEY, Username nvarchar(50) COLLATE Latin1_General_100_CI_AS NOT NULL UNIQUE, PasswordHash nvarchar(300) NOT NULL, RoleId int NOT NULL REFERENCES Roles(Id), IsActive bit NOT NULL DEFAULT 1, FailedCount int NOT NULL DEFAULT 0, FailureWindow datetimeoffset NULL, LockedUntil datetimeoffset NULL, LastLoginAt datetimeoffset NULL, Version rowversion);
CREATE TABLE Sessions(Id uniqueidentifier PRIMARY KEY, UserId bigint NOT NULL REFERENCES Users(Id), LastActivity datetimeoffset NOT NULL, IsClosed bit NOT NULL DEFAULT 0);
CREATE TABLE Categories(Id bigint IDENTITY PRIMARY KEY, Name nvarchar(100) COLLATE Latin1_General_100_CI_AS NOT NULL UNIQUE, IsActive bit NOT NULL DEFAULT 1, Version rowversion);
CREATE TABLE Units(Id bigint IDENTITY PRIMARY KEY, Name nvarchar(30) COLLATE Latin1_General_100_CI_AS NOT NULL UNIQUE, IsActive bit NOT NULL DEFAULT 1, Version rowversion);
CREATE TABLE Products(Id bigint IDENTITY PRIMARY KEY, SKU nvarchar(30) COLLATE Latin1_General_100_CI_AS NOT NULL UNIQUE, Name nvarchar(150) NOT NULL, CategoryId bigint NOT NULL REFERENCES Categories(Id), UnitId bigint NOT NULL REFERENCES Units(Id), Minimum int NOT NULL DEFAULT 0 CHECK(Minimum>=0), SellingPrice decimal(19,4) NULL CHECK(SellingPrice>=0), Notes nvarchar(500) NULL, IsActive bit NOT NULL DEFAULT 1, Version rowversion);
CREATE TABLE StockBalances(ProductId bigint PRIMARY KEY REFERENCES Products(Id), Quantity int NOT NULL DEFAULT 0 CHECK(Quantity>=0), InventoryValue decimal(19,4) NOT NULL DEFAULT 0 CHECK(InventoryValue>=0), Version rowversion, CONSTRAINT CK_EmptyBalance CHECK(Quantity<>0 OR InventoryValue=0));
CREATE SEQUENCE DocumentSequence AS bigint START WITH 1 INCREMENT BY 1;
CREATE TABLE Stocktakes(Id bigint IDENTITY PRIMARY KEY, Number nvarchar(40) NOT NULL UNIQUE, Status nvarchar(20) NOT NULL DEFAULT 'OPEN' CHECK(Status IN('OPEN','POSTED','CANCELLED')), CreatedBy bigint NOT NULL REFERENCES Users(Id), CreatedAt datetimeoffset NOT NULL DEFAULT TODATETIMEOFFSET(SYSUTCDATETIME(),'+00:00'), PostedBy bigint NULL REFERENCES Users(Id), PostedAt datetimeoffset NULL, RequestId uniqueidentifier NULL, Version rowversion);
CREATE UNIQUE INDEX UX_StocktakeRequest ON Stocktakes(RequestId) WHERE RequestId IS NOT NULL;
CREATE TABLE StockDocuments(Id bigint IDENTITY PRIMARY KEY, Number nvarchar(40) NOT NULL UNIQUE, Type nvarchar(30) NOT NULL CHECK(Type IN('OPENING','IN','OUT','QUANTITY_ADJUSTMENT','VALUE_ADJUSTMENT')), Status nvarchar(20) NOT NULL DEFAULT 'DRAFT' CHECK(Status IN('DRAFT','POSTED','CANCELLED')), CreatedBy bigint NOT NULL REFERENCES Users(Id), CreatedAt datetimeoffset NOT NULL DEFAULT TODATETIMEOFFSET(SYSUTCDATETIME(),'+00:00'), PostedBy bigint NULL REFERENCES Users(Id), PostedAt datetimeoffset NULL, Reason nvarchar(500) NULL, ExternalReference nvarchar(150) NULL, ReferenceDocumentId bigint NULL REFERENCES StockDocuments(Id), StocktakeId bigint NULL REFERENCES Stocktakes(Id), RequestId uniqueidentifier NULL, ContentHash nvarchar(64) NULL, Version rowversion);
CREATE UNIQUE INDEX UX_DocumentRequest ON StockDocuments(RequestId) WHERE RequestId IS NOT NULL;
CREATE UNIQUE INDEX UX_DocumentStocktake ON StockDocuments(StocktakeId) WHERE StocktakeId IS NOT NULL;
CREATE TABLE StockDocumentLines(Id bigint IDENTITY PRIMARY KEY, DocumentId bigint NOT NULL REFERENCES StockDocuments(Id), ProductId bigint NOT NULL REFERENCES Products(Id), Quantity int NOT NULL CHECK(Quantity>=0), Direction nvarchar(3) NULL CHECK(Direction IN('IN','OUT')), UnitCostInput decimal(19,4) NULL CHECK(UnitCostInput>0), PostedUnitCost decimal(19,4) NULL, PostedValue decimal(19,4) NULL, SKU nvarchar(30) NULL, ProductName nvarchar(150) NULL, UnitName nvarchar(30) NULL, SnapshotQuantity int NULL, SnapshotValue decimal(19,4) NULL, BalanceVersion varbinary(8) NULL, TargetValue decimal(19,4) NULL, CalculationBasis nvarchar(500) NULL, CONSTRAINT UX_DocumentProduct UNIQUE(DocumentId,ProductId));
CREATE TABLE StockLedger(Id bigint IDENTITY PRIMARY KEY, DocumentLineId bigint NOT NULL UNIQUE REFERENCES StockDocumentLines(Id), ProductId bigint NOT NULL REFERENCES Products(Id), QuantityDelta int NOT NULL, ValueDelta decimal(19,4) NOT NULL, QuantityAfter int NOT NULL CHECK(QuantityAfter>=0), ValueAfter decimal(19,4) NOT NULL CHECK(ValueAfter>=0), PostedAt datetimeoffset NOT NULL, CHECK(QuantityDelta<>0 OR ValueDelta<>0));
CREATE TABLE StocktakeLines(Id bigint IDENTITY PRIMARY KEY, StocktakeId bigint NOT NULL REFERENCES Stocktakes(Id), ProductId bigint NOT NULL REFERENCES Products(Id), QuantitySnapshot int NOT NULL, ValueSnapshot decimal(19,4) NOT NULL, BalanceVersion varbinary(8) NOT NULL, CountedQuantity int NULL CHECK(CountedQuantity>=0), Reason nvarchar(500) NULL, ZeroStockUnitCost decimal(19,4) NULL CHECK(ZeroStockUnitCost>0), CountedBy bigint NULL REFERENCES Users(Id), CONSTRAINT UX_StocktakeProduct UNIQUE(StocktakeId,ProductId));
CREATE TABLE AuditLogs(Id bigint IDENTITY PRIMARY KEY, ActorId bigint NULL REFERENCES Users(Id), OccurredAt datetimeoffset NOT NULL DEFAULT TODATETIMEOFFSET(SYSUTCDATETIME(),'+00:00'), Action nvarchar(60) NOT NULL, Entity nvarchar(60) NOT NULL, EntityId nvarchar(80) NULL, BeforeValue nvarchar(max) NULL, AfterValue nvarchar(max) NULL, Result nvarchar(20) NOT NULL, CorrelationId uniqueidentifier NOT NULL);
CREATE TABLE CorrectionNotes(Id bigint IDENTITY PRIMARY KEY, DocumentId bigint NOT NULL REFERENCES StockDocuments(Id), ActorId bigint NOT NULL REFERENCES Users(Id), CreatedAt datetimeoffset NOT NULL, Note nvarchar(500) NOT NULL);
CREATE TABLE Settings([Key] nvarchar(80) PRIMARY KEY, [Value] nvarchar(2000) NOT NULL);
INSERT Settings VALUES('StoreName',N'Toko Saya'),('TimeZone','Asia/Jakarta'),('Maintenance','false'),('LanEnabled','false');
CREATE INDEX IX_ProductName ON Products(Name) INCLUDE(SKU,CategoryId,IsActive);
CREATE INDEX IX_ProductCategory ON Products(CategoryId,IsActive) INCLUDE(SKU,Name,Minimum);
CREATE INDEX IX_LedgerProduct ON StockLedger(ProductId,Id) INCLUDE(QuantityDelta,ValueDelta,PostedAt,QuantityAfter,ValueAfter);
CREATE INDEX IX_DocumentsPosted ON StockDocuments(Status,PostedAt DESC) INCLUDE(Number,Type,CreatedBy);
CREATE INDEX IX_AuditTime ON AuditLogs(OccurredAt DESC);
